import java.util.Scanner;

public class ConvCheck {
    public static void main(String[] args) {
        Scanner sysIn = new Scanner(System.in);
        int wPos = sysIn.nextInt();
        int mVal = sysIn.nextInt();
        int outcome = 1;

        while (mVal != 0) {
            int rem = mVal % wPos;
            if (rem == wPos - 1 && rem != 1) {
                mVal = (mVal + 1) / wPos;
            } else if (rem == 1) {
                mVal /= wPos;
            } else {
                if (rem != 0) {
                    outcome = 0;
                    break;
                }
                mVal /= wPos;
            }
        }
        System.out.print(outcome == 1 ? "YES" : "NO");
        sysIn.close();
    }
}
